    issues.push(...this.detectInlineDataURIs(filename, root));
    issues.push(...this.detectExcessiveImportant(filename, root));
    issues.push(...this.detectDeepSelectors(filename, root));
    issues.push(...this.detectDuplicateSelectors(filename, root));
    issues.push(...this.detectRenderBlockingPatterns(filename, root));
