          severity: 'warning',
          type: 'non-composited-animation',
          file: filename,
          line: atRule.source && atRule.source.start ? atRule.source.start.line : 1,
          property: offending,
          keyframeName,
          message: `@keyframes "${keyframeName}" animates non-composited property "${offending}". This forces layout/paint on every frame.`,
          recommendation: `Replace "${offending}" animation with "transform" equivalent (e.g. translateX/Y for left/top, scaleX/Y for width/height). Non-composited animations cause jank.`,
